cat >> tests/forms_test.sh.new <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle(legacy)"; fail=1; }
# Cirrus Function URL accepts only A-Z a-z 0-9 _ . - in query keys (docs/platform/cirrus-functions.md)
for f in event refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="//;s/"$//' | while read -r u; do
    k=${u#\?}; k=${k%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || exit 1
  done || { echo "render emits invalid query key ($f)"; fail=1; }
done
bash bin/render event | grep -o 'action="[^"]*"' | head -1 | sed 's/action="//;s/"$//' > /tmp/u.$$
bash bin/handle POST "/events/1/edit$(cat /tmp/u.$$)" | grep -q '^200 ' || { echo "rendered url not handled"; fail=1; }
rm -f /tmp/u.$$
exit $fail
EOF
mv tests/forms_test.sh.new tests/forms_test.sh; bash tests/forms_test.sh; echo rc=$?

cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must only use A-Z a-z 0-9 _ . - : the Cirrus function URL rejects other keys (EVT-412).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing. The old form (?/name) is still accepted.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; /*) echo "${1#/}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーに `/` を使わない。Cirrus の Function URL が拒否するため。旧形式 `?/<操作名>` も受け付ける）|' docs/framework.md
bash scripts/verify.sh; echo rc=$?; bash bin/render refund; grep -rn '?/' lib bin app docs | grep -v legacy
